ating-forum-the-ipc-surface-finish-specifications/129300/pcb","source_date":"2021-10-06","source_note":"G. Milad, Plating Forum: 'EN thickness shall be 3 to 6 um (118.1 to 236.2 uin)'. Same Ni range carried into IPC-4552A."},{"item_key":null,"process":"ENIG","parameter":"immersion gold thickness (IPC-4552, 2002)","value_min":0.05,"value_max":0.05,"unit":"um","machine_or_line":null,"source_url":"https://iconnect007.com/article/129297/the-plating-forum-the-ipc-surface-finish-specifications/129300/pcb","source_date":"2021-10-06","source_note":"Original spec: minimum 0.05 um (1.97 uin) at 4 sigma below mean, no upper limit; typical 0.075-0.125 um. 2012 amendment lowered min to 0.04 um (1.6 uin) with restrictions."},{"item_key":"gold_thickness_um","process":"ENIG","parameter":"immersion gold thickness (IPC-4552A, 2017)","value_min":0.04,"value_max":0.1,"unit":"um","machine_or_line":null,"source_url":"https://iconnect007.com/article/129297/the-plating-forum-the-ipc-surface-finish-specifications/129300/pcb","source_date":"2021-10-06","source_note":"IPC-4552A: 0.04-0.1 um (1.6-4.0 uin), first spec with an upper limit. IPC-4552B (2021) gold limits not sourced (ANSI preview 403)."},{"item_key":null,"process":"ENIG","parameter":"immersion gold thickness, recommended","value_min":1.6,"value_max":2.8,"unit":"uin","machine_or_line":null,"source_url":"https://www.uyemura.com/articles/Milad-IPC-4552-rev-A-for-ENIG.pdf","source_date":"2026-11-23","source_note":"Uyemura paper (Milad, Bengston, Gruenwald) 'Eliminating Ni Corrosion in ENIG/ENEPIG Using Reduction Assisted Immersion Gold': 'recommended thickness of 1.6 - 2.8 uins'. Undated; text says IPC-4552 Rev B in final draft (2019). PDF served at this URL despite filename."},{"item_key":"nickel_thickness_um","process":"ENIG","parameter":"electroless nickel thickness, typical","value_min":3,"value_max":5,"unit":"um","machine_or_line":null,"source_url":"https://19january2021snapshot.epa.gov/sites/static/files/2013-12/documents/pwb_surface_finishes_guide.pdf","source_date":"2000-03-01","source_note":"US EPA 744-R-00-002 (March 2000) DfE surface finishes guide: Ni 'typically 120 to 200 microinches (3 to 5 microns)'. Document dated by month only; day set to 01."},{"item_key":"gold_thickness_um","process":"ENIG","parameter":"immersion gold thickness, typical","value_min":0.05,"value_max":0.2,"unit":"um","machine_or_line":null,"source_url":"https://19january2021snapshot.epa.gov/sites/static/files/2013-12/documents/pwb_surface_finishes_guide.pdf","source_date":"2000-03-01","source_note":"EPA guide: gold 'typically 3 to 7 microinches (0.05 to 0.2 microns)'. Document dated by month only; day set to 01."},{"item_key":"nickel_thickness_um","process":"ENIG","parameter":"electroless nickel thickness, fab-house stated","value_min":3,"value_max":6,"unit":"um","machine_or_line":"JLCPCB","source_url":"https://jlcpcb.com/help/article/jlcpcb-surface-finish","source_date":"2026-11-23","source_note":"JLCPCB help article: 'Nickel thickness: approximately 3-6 micrometers'."},{"item_key":"gold_thickness_um","process":"ENIG","parameter":"immersion gold thickness, fab-house stated","value_min":0.025,"value_max":0.05,"unit":"um","machine_or_line":"JLCPCB","source_url":"https://jlcpcb.com/help/article/jlcpcb-surface-finish","source_date":"2026-11-23","source_note":"JLCPCB help article: gold 'approximately 0.025-0.05 micrometers'; also offers 1 or 2 uin."},{"item_key":null,"process":"ENIG","parameter":"electroless nickel deposition rate","value_min":12,"value_max":12,"unit":"um/h","machine_or_line":"Umicore NIMUDEN NPR-series","source_url":"https://umicore.com/en/api/fw/file/1bf520f29dc7da6fa149a7b7806b04edaf724d5f","source_date":"2019-04-16","source_note":"Umicore ENIG-PROCESS sheet (Version 16 April 2019): 'Deposition rate approx. 12 um / h'."},{"item_key":null,"process":"ENIG","parameter":"electroless nickel bath temperature","value_min":80,"value_max":84,"unit":"degC","machine_or_line":"Umicore NIMUDEN NPR-series","sou